-- cdk_parts_pick_ticket (parts-pick-ticket) -- Parts Pick Ticket
-- Parts Pick Ticket
-- SAP analogue: Transfer Order / Reservation withdrawal document (LB03/MB1B analogue)
-- grain: one row per pick-ticket line
-- api reach: partial
-- generated by schema/bin/gen_ddl.py from contract EgD-CDK-FIELDS-v2 -- do not hand-edit, regenerate instead

CREATE TABLE IF NOT EXISTS cdk_parts_pick_ticket (
    pick_ticket_id VARCHAR(20) NOT NULL,
    ro_number VARCHAR(20),
    counter_sale_id VARCHAR(20),
    part_number VARCHAR(20),
    quantity_picked NUMBER(13,3),
    pick_bin_location VARCHAR(10),
    picked_by_employee_id VARCHAR(10),
    pick_date DATE,
    pick_status VARCHAR(32),
    _rooftop_id VARCHAR(20),
    _extracted_at TIMESTAMP_NTZ,
    _source_route VARCHAR(16),
    _batch_id VARCHAR(64),
    PRIMARY KEY (pick_ticket_id)
);

-- Column comments (dealer-language label + confidence mark: [D]=documented [I]=inferred [U]=unverified)
COMMENT ON COLUMN cdk_parts_pick_ticket.pick_ticket_id IS '[D] Pick Ticket ID';
