COMMENT ON COLUMN cdk_parts_pick_ticket.quantity_picked IS '[I] Quantity Picked';
COMMENT ON COLUMN cdk_parts_pick_ticket.pick_bin_location IS '[I] Pick Bin Location';
COMMENT ON COLUMN cdk_parts_pick_ticket.picked_by_employee_id IS '[I] Picked-By Employee ID';
COMMENT ON COLUMN cdk_parts_pick_ticket.pick_date IS '[I] Pick Date';
COMMENT ON COLUMN cdk_parts_pick_ticket.pick_status IS '[I] Pick Status (values: OPEN=Not yet picked; PICKED=Picked, awaiting issue; ISSUED=Issued to RO/counter sale)';
COMMENT ON COLUMN cdk_parts_pick_ticket._rooftop_id IS '[D] which rooftop/store this extracted row belongs to';
COMMENT ON COLUMN cdk_parts_pick_ticket._extracted_at IS '[D] when this row was pulled from CDK by the extract harness';
COMMENT ON COLUMN cdk_parts_pick_ticket._source_route IS '[D] which of the three extract routes produced this row: fortellis | export | screen';
